var nameDevive = metadata.deviceName.split("-");
var procesamiento = JSON.parse(metadata.acondicionamientoGATEWAY);

function procesarMediciones(mediciones, operaciones) {
    var resultado = {};

    for (var clave in mediciones) {
        if (operaciones[clave]) {
            try {
                var valor = mediciones[clave];

                // Verificar qué operación realizar
                if (operaciones[clave] === "truncate") {
                    // Truncar a 2 decimales
                    resultado[clave] = Math.floor(valor * 100) / 100;
                } else if (operaciones[clave] === "round") {
                    // Redondear a 2 decimales
                    resultado[clave] = Math.round(valor * 100) / 100;
                } else {
                    // Si no es ninguna de las operaciones anteriores, aplicar operación matemática
                    resultado[clave] = eval(valor + operaciones[clave]);
                }

                // Se usa eval() para evaluar la operación sobre el valor
                //resultado[clave] = eval(mediciones[clave] + operaciones[clave]);
            } catch (error) {
                resultado[clave] = mediciones[clave]; // En caso de error, mantener el valor original
            }
        } else {
            resultado[clave] = mediciones[clave]; // Si no hay operación, dejar el valor igual
        }
    }

    return resultado;
}

if(procesamiento[nameDevive[0]] !== undefined){
    msg = procesarMediciones(msg, procesamiento[nameDevive[0]])
}

delete metadata.acondicionamientoGATEWAY;
delete metadata.datosRequeridosGATEWAY;

return {msg: msg, metadata: metadata, msgType: msgType};

metadata.token = metadata.credentials;

delete metadata.credentials;
delete metadata.credentialsType;

return {msg: msg, metadata: metadata, msgType: msgType};

function validarSiExisteDispositivo(token, dispositivos){
    dispositivos = dispositivos["GATEWAY"];

    for (var key in dispositivos) {
        if (dispositivos.hasOwnProperty(key)) {
            var items = dispositivos[key];

            if (Array.isArray(items)) {
                for (var i = 0; i < items.length; i++) {
                    if (items[i] === token) {
                        var data = {
                            dispositivo: "GATEWAY",
                            tipoDispositivo: key,
                            posicion: i,
                            token: token
                        };

                        return data;
                    }
                }
            } else {
                for (var subKey in items) {
                    if (items.hasOwnProperty(subKey)) {
                        var subItems = items[subKey];
                        for (var j = 0; j < subItems.length; j++) {
                            if (subItems[j] === token) {
                                var data = {
                                    dispositivo: "GATEWAY",
                                    tipoDispositivo: key,
                                    posicion: j,
                                    subTipo: subKey,
                                    token: token
                                };

                                return data;
                            }
                        }
                    }
                }
            }
        }
    }


    return false;
}

function buscarDispositivoSitio(token, sitios){
    if(sitios[token] !== undefined){
        return sitios[token];
    }

    return false;
}

var config = JSON.parse(metadata.dispositivos);
var sitios = JSON.parse(metadata.sitios);

var dispositivo = validarSiExisteDispositivo(metadata.token, config);
if(!dispositivo){
    var newMetadata = {
        'deviceType': metadata.deviceType,
        'deviceName': metadata.deviceName,
        'ts': metadata.ts
    };

    var newMSG = {
        'error_nodo': "NoExisteDispositivoEnDispositivos",
        'error_msg' : msg,
        'error_metadata' : newMetadata
    };

    return {msg: newMSG, metadata: newMetadata, msgType: msgType};
}

dispositivo["sitios"] = parseInt(metadata.numSitios);

var informacionSitio = buscarDispositivoSitio(dispositivo.token, sitios);
if(!informacionSitio){
    var newMetadata = {
        'deviceType': metadata.deviceType,
        'deviceName': metadata.deviceName,
        'ts': metadata.ts
    };

    var newMSG = {
        'error_nodo': "NoExisteDispositivoEnSitio",
        'error_msg' : msg,
        'error_metadata' : newMetadata
    };

    return {msg: newMSG, metadata: newMetadata, msgType: msgType};
}

dispositivo["nombreSitio"] = informacionSitio;

metadata.dispositivo = JSON.stringify(dispositivo);

delete metadata.token;
delete metadata.dispositivos;
delete metadata.sitios;
delete metadata.numSitios;

return {msg: msg, metadata: metadata, msgType: msgType};

