if(metadata.ss_acondicionar !== undefined){
    dispositivo.acondicionar = JSON.parse(metadata.ss_acondicionar);
}

metadata.dispositivo = JSON.stringify(dispositivo);

delete metadata.ss_histeresis;
delete metadata.ss_umbrales;
delete metadata.ss_acondicionar;
delete metadata.ss_alias;

return {msg: msg, metadata: metadata, msgType: msgType};

